[Form]
public class METProcessPackChange extends FormRun
{
            
    InventItemPurchSetup inventItemPurchSetupTempItem;
    InventItemPurchSetup inventItemPurchSetupOrigItem;
    InventItemSalesSetup inventItemSalesSetupTempItem;
    InventItemSalesSetup inventItemSalesSetupOrigItem;
    METInventItemOrderSetup metInventItemOrderSetup;
    METInventItemOrderSetup metInventItemOrderSetupTemp;

    InventTable inventTable;
    METInventTable metInventTable;
    InventItemBarcode inventItemBarcodeOrig;
    InventItemBarcode inventItemBarcodeTemp;    
    WHSPhysDimUOM whsPhysDimUOMOrig;
    WHSPhysDimUOM whsPhysDimUOMTemp;
    
    InventDim inventDim;

}

    /// <summary>
    /// Initialise form control values
    /// </summary>
    private void initControls()
    {
        ItemId tempItemId;

        tempItemId = metInventItemOrderSetup.TempItemPackChg;
            
        inventDim = InventDim::find(metInventItemOrderSetup.InventDimId);

        inventTable = InventTable::find(metInventItemOrderSetup.ItemId);
        metInventTable = METInventTable::find(metInventItemOrderSetup.ItemId);
        inventItemPurchSetupOrigItem = InventItemPurchSetup::find(metInventItemOrderSetup.ItemId, inventDim.inventDimId);
        inventItemPurchSetupTempItem = InventItemPurchSetup::find(tempItemId, inventDim.inventDimId);
        inventItemSalesSetupOrigItem = InventItemSalesSetup::find(metInventItemOrderSetup.ItemId, inventDim.inventDimId);
        inventItemSalesSetupTempItem = InventItemSalesSetup::find(tempItemId, inventDim.inventDimId);
        
        //metInventItemOrderSetup      = METInventItemOrderSetup::findByItemAndSite(metInventItemOrderSetup.ItemId, inventDim.InventSiteId);
            
        whsPhysDimUOMOrig = METItemPackChangeHelper::getWhsPhysDimOUM(inventTable.ItemId);
        whsPhysDimUOMTemp = METItemPackChangeHelper::getWhsPhysDimOUM(tempItemId);
        metInventItemOrderSetupTemp = METItemPackChangeHelper::getItemSiteSettingsSetup(tempItemId, metInventItemOrderSetup.SiteId);

        //Display original item data
        PurchOrderUnit.text(inventItemPurchSetupOrigItem.METPurchUnit);
        SalesOrderUnit.text(inventItemSalesSetupOrigItem.METSalesUnit);
        ProductName.text(inventTable.itemName());
        ItemSubrange.text(metInventItemOrderSetup.SubrangeId);
        Barcode.text(METItemPackChangeHelper::getInventItembarcode(inventTable.ItemId, inventDim, inventItemPurchSetupOrigItem.METPurchUnit));
        InventUnit.text(inventTable.inventTableModuleInvent().UnitId);
        InventBarcode.text(METItemPackChangeHelper::getInventItembarcode(inventTable.ItemId, inventDim, inventTable.inventTableModuleInvent().UnitId));
        SalesBarcode.text(METItemPackChangeHelper::getInventItembarcode(inventTable.ItemId, inventDim, inventItemSalesSetupOrigItem.METSalesUnit));
        VendorListPrice.realValue(METItemPackChangeHelper::getVendorListPrice(inventTable.ItemId, inventDim));

        //Display temp item data
        InventTable inventTableTemp = InventTable::find(inventItemPurchSetupTempItem.ItemId);
        InventDim inventDimTemp = InventDim::find(metInventItemOrderSetupTemp.InventDimId);
        PurchOrderUnitTemp.text(inventItemPurchSetupTempItem.METPurchUnit);
        SalesOrderUnitTemp.text(inventItemSalesSetupTempItem.METSalesUnit);
        ProductNameTemp.text(InventTable::find(tempItemId).itemName());
        ItemSubrangeTemp.text(metInventItemOrderSetupTemp.SubrangeId);
        ItemBarcodeTemp.text(METItemPackChangeHelper::getInventItembarcode(inventTableTemp.ItemId, inventDimTemp, inventItemPurchSetupTempItem.METPurchUnit));
        InventUnitTemp.text(inventTableTemp.inventTableModuleInvent().UnitId);
        InventBarcodeTemp.text(METItemPackChangeHelper::getInventItembarcode(inventTableTemp.ItemId, inventDimTemp, inventTable.inventTableModuleInvent().UnitId));
        SalesBarcodeTemp.text(METItemPackChangeHelper::getInventItembarcode(inventTableTemp.ItemId, inventDimTemp, inventItemSalesSetupTempItem.METSalesUnit));
        VendorListPriceTemp.realValue(METItemPackChangeHelper::getVendorListPrice(inventTableTemp.ItemId, inventDimTemp));
    }

    /// <summary>
    /// The canCose method of the form.
    /// </summary>
    /// <returns>True or false</returns>
    public boolean canClose()
    {
        boolean canClose = super();

        if (element.closedOk() && canClose)
        {   
            METItemPackChangeHelper metItemPackChangeHelper = new METItemPackChangeHelper();

            metItemPackChangeHelper.parmMETInventItemOrderSetup(metInventItemOrderSetup);
            metItemPackChangeHelper.parmMETInventItemOrderSetupTempItem(metInventItemOrderSetupTemp);
            //metItemPackChangeHelper.parmInventItemBarcodeOrigItem(inventItemBarcodeOrig);
            //metItemPackChangeHelper.parmInventItemBarcodeTempItem(inventItemBarcodeTemp);
            metItemPackChangeHelper.parmInventItemPurchSetupOrigItem(inventItemPurchSetupOrigItem);
            metItemPackChangeHelper.parmInventItemPurchSetupTempItem(inventItemPurchSetupTempItem);
            metItemPackChangeHelper.parmInventItemSalesSetupOrigItem(inventItemSalesSetupOrigItem);
            metItemPackChangeHelper.parmInventItemSalesSetupTempItem(inventItemSalesSetupTempItem);
            metItemPackChangeHelper.parmWHSPhysDimUOMOrigItem(whsPhysDimUOMOrig);
            metItemPackChangeHelper.parmWHSPhysDimUOMTempItem(whsPhysDimUOMTemp);

            if (metItemPackChangeHelper.validate())
            {
                metItemPackChangeHelper.startOperation();
            }
            else
            {
                canClose = false;
            }
        }

        return canClose;
    }

        /// <summary>
        /// The lookup method of string control
        /// </summary>
        public void lookup()
        {
            Query                   query = new Query();
            QueryBuildDataSource    queryBuildDataSource;
            SysTableLookup          sysTableLookup;

            sysTableLookup = SysTableLookup::newParameters(tableNum(InventTable), this);
            queryBuildDataSource = query.addDataSource(tableNum(InventTable));
                       
            sysTableLookup.addLookupField(fieldNum(InventTable, ItemId));

            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }

        /// <summary>
        /// The modified method of the form control
        /// </summary>
        /// <returns>True or false</returns>
        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            if (ItemId.text() && SiteId.text())
            {
                metInventItemOrderSetup = METItemPackChangeHelper::getItemSiteSettingsSetup(ItemId.text(), siteId.text());
                element.initControls();
            }
        
            return ret;
        }

        /// <summary>
        /// The lookup method of string control
        /// </summary>
        public void lookup()
        {
            Query                   query = new Query();
            QueryBuildDataSource    queryBuildDataSource;
            SysTableLookup          sysTableLookup;

            sysTableLookup = SysTableLookup::newParameters(tableNum(METInventItemOrderSetup), this);
            queryBuildDataSource = query.addDataSource(tableNum(METInventItemOrderSetup));
            
            queryBuildDataSource.fields().clearFieldList();
            queryBuildDataSource.fields().addField(fieldNum(METInventItemOrderSetup, SiteId));
            queryBuildDataSource.addRange(fieldNum(METInventItemOrderSetup, ItemId)).value(ItemId.text());
                
            sysTableLookup.addLookupField(fieldNum(METInventItemOrderSetup, SiteId));

            sysTableLookup.parmUseLookupValue(NoYes::No);
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }

        /// <summary>
        /// The modified method of the form control
        /// </summary>
        /// <returns>True or false</returns>
        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            if (ItemId.text() && SiteId.text())
            {
                metInventItemOrderSetup = METItemPackChangeHelper::getItemSiteSettingsSetup(ItemId.text(), siteId.text());
                element.initControls();
            }
        
            return ret;
        }
